def authorization_schema(selection):
 sha={'type':'string','pattern':'^[0-9a-f]{64}$'};sources={'type':'object','minProperties':1,'additionalProperties':sha};work={k:{'type':'integer','minimum':0 if k in ('max_FEM_calls','max_OC_calls') else 1} for k in WORK}
 props=dict(schema_version={'const':SCHEMA},manifest_sha256={'const':PLAN_SHA},authorization_id={'type':'string','minLength':8},kind={'enum':['production','resource_qualification']},stage={'type':'integer','minimum':1,'maximum':5},approved_ids={'type':'array','minItems':1,'maxItems':30,'uniqueItems':True,'items':{'enum':sorted(selection.jobs)}},output_root={'type':'string'},production_sources=sources,validation_sources=sources,implementation_sources=sources,environment={'type':'object','required':['python','platform','packages','threads'],'additionalProperties':False,'properties':{'python':{'type':'string'},'platform':{'type':'string'},'packages':{'type':'object'},'threads':{'type':'object'}}},limits={'const':LIMITS},stop_rules={'const':STOP},maximum_work={'type':'object','required':sorted(WORK),'properties':work,'additionalProperties':False},approval={'type':'object','required':['identity','approved_at','expires_at','decision_reference'],'additionalProperties':False,'properties':{k:{'type':'string','minLength':1} for k in ('identity','approved_at','expires_at','decision_reference')}},experiment={'type':'object','required':['actions','max_new_updates','release_allowed','original_spec_unchanged'],'additionalProperties':False,'properties':{'actions':{'type':'array','minItems':1,'uniqueItems':True,'items':{'enum':['generate','resume','replay','supplemental','adopt']}},'max_new_updates':{'type':['integer','null'],'minimum':1,'maximum':500},'release_allowed':{'type':'boolean'},'original_spec_unchanged':{'const':True}}},resume_bindings={'type':'object'},qualification_evidence={'type':'object'},disk_requirement_bytes={'type':'integer','minimum':1})
 assert set(props)==FIELDS
 return {'$schema':'https://json-schema.org/draft/2020-12/schema','$id':'urn:m3:5b2:authorization:v1','type':'object','required':sorted(FIELDS),'additionalProperties':False,'properties':props,'description':'Schema is inert. Python validator additionally checks exact source/environment/ID/stage/root/work/qualification semantics. Only a matching digest in the protected externally issued approval book can activate dispatch.'}

def qualification_proposal(s):
 cases=[]
 for i in sorted(BLOCKERS):
  pid=next(p for p,j in s.jobs.items() if j['plan_index']==i);j=s.jobs[pid]
  cases.append(dict(plan_index=i,problem_id=pid,family=j['family'],partition=j['partition'],spec_reference=j['problem_spec'],spec_sha256=j['spec_sha256'],source_id=s.manifest['source_binding']['original_execution_source_id'],scientific_reason=j['rationale'],resource_uncertainty=j['resource']['qualification'],execution_authorized=False,authorization_issued=False,expected_future_output_root=str(ROOT/f'm3_5b2/executions/qualification_plan{i}_NOT_AUTHORIZED'),kind='resource_qualification',stage=j['resource']['stage'],recommended_experiment='One bounded original-spec run with original500-update cap and original first stopping point, then complete independent replay and supplemental checks; zero automatic retries',maximum_work=dict(max_ids=1,max_worker_jobs=4,max_FEM_calls=1506,max_OC_calls=1000,max_states_per_id=501,max_updates_per_id=500,max_total_worker_seconds=3600),limits=LIMITS,disk_requirement_bytes=minimum_disk_bytes(s,[pid]),optional_prefix_diagnostic=dict(max_new_updates=2,max_states=3,max_FEM_calls=3,max_OC_calls=2,max_worker_jobs=1,max_worker_seconds=900,strictly_diagnostic=True,may_not_establish_full_cap_qualification=True,auto_followup=False),release_allowed=False,possible_completed_artifact='If the original stop is reached, retain a mechanically accepted qualification history. Never publish it automatically as production; separate explicit read-only adoption authority is required, with no regeneration.',sufficient_subsequent_evidence=['Exact case/source/spec and environment bindings','Native hashes, exact checkpoint bytes, complete raw independent state/transition operands','Unchanged equilibrium/boundary/compliance/gradient/OC/multiplier and strict feasibility gates','v2/v3 pass, actual stop metadata retained, no reference labels','HWM/RSS/combined/time monitors, actual FEM/OC counts, durable work ledger and no hidden retries','Actual501-state/full-cap residency required by current96 production gate; early stopping is not evidence for501' if i in (145,151) else 'Full original-stop generation/replay/supplemental resource evidence for this exact case, not inferred from another case'],stop_conditions=['Any failed source/authorization/registry/environment/disk gate','Any failed numerical or resource gate','Budget/deadline exhausted','Checkpoint/control evidence missing or corrupt'],quarantine_conditions=['Failed/incomplete output excluded from ML release','All logs, counters, monitors and committed bytes retained','No automatic restart, replacement ID or shortened stopping'],recovery_rule='Any later resume needs a separately issued exact prior-journal/work-ledger binding and real same-spec control evidence for unchanged categoryC. If unavailable, remain blocked; never start a fresh duplicate.',full_cap_96_caveat='If original stopping occurs before501, keep actual termination; do not continue past it or label a prefix full-cap qualified. Any alternative residency diagnostic needs its own reviewed scope and cannot certify new FEM states.'))
 return dict(schema_version='m3.5b2.qualification_proposal.v1',manifest_sha256=PLAN_SHA,execution_authorized=False,authority=False,new_work_performed=0,cases=cases,recommended_first_case=98)

def main(out):
 out=Path(out).resolve();check((out/'protected_before.json').is_file(),'Baseline must precede implementation');check(not (out/'artifact_manifest.json').exists(),'Immutable report output already exists')
 s=Selection();s.verify_sources();registry=Registry(ROOT,s);write(out/'global_duplicate_registry.json',registry.report())
 conflicts=[]
 for pid in s.jobs:
  try:registry.eligible(pid)
  except ValueError as exc:
   eq=equivalent(s.specs[pid]);records=[dict(problem_id=other,**r) for other,rs in registry.records.items() for r in rs if other==pid or r['equivalence_sha256']==eq]
   conflicts.append(dict(plan_index=s.jobs[pid]['plan_index'],selected_id=pid,equivalence_sha256=eq,error=str(exc),historical_records=records,decision='Blocked. No regeneration, ID rename, adoption or selection change is authorized. Explicit provenance review required.'))
 write(out/'configuration_equivalence_conflicts.json',conflicts)
 assert len(conflicts)==1 and conflicts[0]['plan_index']==10
 write(out/'authorization.schema.json',authorization_schema(s));write(out/'resource_qualification_proposal.json',qualification_proposal(s))
 check(read(Path(__file__).with_name('approved_receipts.json'))['approved_authorizations']==[],'No executable authorization permitted in this task');check(digest(Path(__file__).with_name('approved_receipts.json'))==APPROVAL_BOOK_SHA,'Empty template integrity')
 # An original-only adapter view verifies real existing data, never fabricates42.
 view=dict(schema_version='m3.5b2.combined_release.v1',manifest_sha256=PLAN_SHA,original_index=dict(path=str(ORIGINAL),sha256=ORIGINAL_SHA),entries=s.original);write(out/'original_only_adapter_view.json',view)
 from .release import ExpandedRelease
 with ExpandedRelease(out/'original_only_adapter_view.json',digest(out/'original_only_adapter_view.json')) as r:real=dict(trajectories=len(r.entries),states=sum(e['states'] for e in r.entries),transitions=sum(e['transitions'] for e in r.entries),new_expansion_entries=0)
 write(out/'actual_release_adapter_verification.json',real)
 for src,name in [('/tmp/m3_5b2_initial_tests.log','initial_tests_47.log'),('/tmp/m3_5b2_final_tests.log','controls_tests_51.log'),('/tmp/m3_5b2_verified_tests.log','normalization_tests_52.log'),('/tmp/m3_5b2_final_verified_tests.log','maps_tests_53.log'),('/tmp/m3_5b2_FINAL_TESTS.log','registry_tests_54.log'),('/tmp/m3_5b2_RELEASE_TESTS.log','source_disk_tests_55.log'),('/tmp/m3_5b2_FROZEN_TESTS.log','thread_tests_58.log'),('/tmp/m3_5b2_ACCEPTANCE_TESTS.log','historical_tests_59.log'),('/tmp/m3_5b2_CERTIFIED_TESTS.log','final_tests.log')]:
  check(Path(src).is_file(),'Missing actual test log '+src);shutil.copyfile(src,out/name)
 check('60 passed' in (out/'final_tests.log').read_text(),'Final60 tests did not pass')
 write(out/'test_outcomes.json',dict(final_passed=60,final_failed=0,earlier_passes=[47,51,52,53,54,55,58,59],scope='Synthetic controls and read-only original-release/evidence checks only; no solver/OC/model work',notes=['An adapter dictionary-construction syntax typo was caught by AST parsing before tests/workers and corrected.','A normalization cache guard was tested to keep borrowed trajectory maps valid during feature extraction.','Synthetic new-entry verifier subclass exists only in test_release.py; default production adapter rejects its fixture authority. No synthetic record establishes physics validity.']))
 source_dir=out/'source_snapshots';source_dir.mkdir();source={}
 for p in Path(__file__).parent.iterdir():
  if p.is_file() and p.suffix in ('.py','.json','.md'):
   archive=source_dir/(p.name+'.txt');shutil.copyfile(p,archive);source[str(p.relative_to(ROOT))]=dict(sha256=digest(p),archive=str(archive.relative_to(out)))
 write(out/'source_manifest.json',source)
 from .documentation import documents
 documents(out,s,registry,conflicts,real)
 protected=read(out/'protected_before.json');changed=[p for p,h in protected.items() if not (ROOT/p).is_file() or digest(ROOT/p)!=h];check(not changed,'Historical source/artifact changed '+str(changed[:10]))
 check(all(digest(ROOT/p)==e['sha256']==digest(out/e['archive']) for p,e in source.items()),'Final source snapshots changed')
 write(out/'source_artifact_integrity.json',dict(passed=True,protected_files=len(protected),changed=changed,frozen_manifest_sha256=digest(PLAN),original_release_index_sha256=digest(ORIGINAL),original_source_archives_verified=77,source_manifest_sha256=digest(out/'source_manifest.json'),approval_template_sha256=APPROVAL_BOOK_SHA,protected_authority_path=str(AUTHORITY_BOOK),authority_created_by_this_task=False,issued_authorizations_created=0,execution_root_created=(ROOT/'m3_5b2/executions').exists(),global_execution_locks_created=(ROOT/'m3_5b2/execution_locks').exists(),new_FEM=0,new_OC=0,new_trajectories=0,new_model_training=0,new_model_inference=0,new_SLURM=0,report_process_HWM_mib=resource.getrusage(resource.RUSAGE_SELF).ru_maxrss/1024))
 write(out/'artifact_manifest.json',{str(p.relative_to(out)):digest(p) for p in out.rglob('*') if p.is_file() and p.name!='artifact_manifest.json'})
 print(json.dumps(dict(status='BLOCKED_BY_INTEGRITY_OR_PROVENANCE',tests_passed=60,tests_failed=0,selected_IDs=30,identity_eligible=29,configuration_equivalent_conflicts=1,real_adapter_trajectories=12,new_work=0)),flush=True)
if __name__=='__main__':main(sys.argv[1])
